def generate_solution():
    """Generate the solution grid based on the pattern analysis."""
    num_pattern_rows = 4
    num_pattern_cols = 4

    # Pattern row starts at grid rows: 1, 8, 15, 22 (0-indexed pattern row 0-3)
    pattern_row_starts = [1, 8, 15, 22]

    # Pattern col starts at grid cols: 1, 8, 15, 22
    pattern_col_starts = [1, 8, 15, 22]

    # Color sequences for the 4-pattern ring groups
    # Position i (1-indexed) maps to:
    # i % 4 == 1: color 3, i % 4 == 2: color 2, i % 4 == 3: color 2, i % 4 == 0: color 4
    # Position i when i % 4 == 0 and i > 4: color 2, 8, 8, 2 for the outer ring
    # Actually, looking at the pattern:
    # Groups of 4 positions: [3,2,2,4] for groups 1, 5, 9, 13...
    # [2,8,8,2] for groups 2, 6, 10, 14...
    # [3,2,2,4] for groups 3, 7, 11, 15...
    # [2,8,8,2] for groups 4, 8, 12, 16...

    def get_color_for_pos(pos):
        """pos is 1-indexed position (1 to 16)"""
        if pos % 4 == 1:
            return 3
        elif pos % 4 == 2:
            # If pos is even: 2, 6, 10, 14 -> 2, 8, 8, 2
            group = pos // 4
            if group % 2 == 0:  # groups 1, 3, 5, 7 in 0-indexed: 0, 1, 2, 3
                return 2
            else:
                return 8
        elif pos % 4 == 3:
            if pos // 4 % 2 == 0:
                return 2
            else:
                return 8
        else:  # pos % 4 == 0
            if pos // 4 % 2 == 0:
                return 4
            else:
                return 2

    grid_solution = []

    for row_idx in range(30):
        new_row = []
        for col_idx in range(30):
            color = 0

            # Check if this is a block left border
            for r in range(num_pattern_rows):
                if row_idx == pattern_row_starts[r]:
                    for c in range(num_pattern_cols):
                        if col_idx == pattern_col_starts[c]:
                            color = 4

            # Check if this is a block right border
            if color == 0:
                for r in range(num_pattern_rows):
                    for c in range(num_pattern_cols):
                        if row_idx in [pattern_row_starts[r], pattern_row_starts[r] + 4]:
                            if col_idx == pattern_col_starts[c] + 6:
                                color = 4

            # Check if this is interior
            if color == 0:
                for r in range(num_pattern_rows):
                    for c in range(num_pattern_cols):
                        interior_row_start = pattern_row_starts[r] + 1
                        interior_row_end = pattern_row_starts[r] + 3
                        interior_col_start = pattern_col_starts[c] + 1
                        interior_col_end = pattern_col_starts[c] + 3
                        if (interior_row_start <= row_idx <= interior_row_end and 
                            interior_col_start <= col_idx <= interior_col_end):
                            pos = r * num_pattern_cols + c + 1
                            color = get_color_for_pos(pos)

            new_row.append(color)
        grid_solution.append(new_row)

    return grid_solution

